package import_body

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "import_body"
	command.Identifiers = []string{"import-body"}
	command.Category = "Server System"
	command.Help = "Infer a route's body json-schema from an example payload"
	command.LongDescription = "Reads one example payload and declares a body property for every key it carries, which is add-body-field run once per key. A route that declared no body becomes a json one here. The inference is a starting point: a type per key, the objects and lists around them, and — with --infer-format — the four formats a string may spell. A property already declared is never written over; --replace starts the schema over instead. Every bound after that is set-body-field's."
	command.Examples = []string{"import-body create-user --file payload.json --required --infer-format"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "json",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the example payload itself, as one json document",
			Examples:    []string{"import-body create-user --json '{\"email\":\"a@b.c\",\"age\":30}'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--json"},
		},
		{
			Id:          "file",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "a file holding the example payload, read instead of --json",
			Examples:    []string{"import-body create-user --file payload.json"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--file"},
		},
		{
			Id:          "required",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "list every key the example carries in its object's required set",
			Examples:    []string{"import-body create-user --file payload.json --required"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--required"},
		},
		{
			Id:          "replace",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "start the schema over instead of adding to the one declared",
			Examples:    []string{"import-body create-user --file payload.json --replace"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--replace"},
		},
		{
			Id:          "infer-format",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "read an email, a uuid, a date-time or a uri back as the format it spells",
			Examples:    []string{"import-body create-user --file payload.json --infer-format"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--infer-format"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route (identifier or package name) that receives the schema",
			Examples:    []string{"import-body create-user --json '{\"email\":\"a@b.c\"}'"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
